import json,numpy as np
from scipy.optimize import least_squares
j=json.load(open('/app/measurements.json'))
for idx in [1,2]:
 m=j['measurements'][idx]
 for s in m['samples']:
  T=np.array(s['temperature']); y=np.array(s.get('one_over_T1',s.get('resistivity'))); sigma=np.array(s['uncertainty']); nu=s['filling']
  mask=(y>0)
  if idx==1:
   if '0.3' in nu: mask&=(T<=1.5)
   if '0.2' in nu: mask&=(T<=.7)
  if idx==2 and '0.2' in nu: continue
  t,y,se=T[mask],y[mask],sigma[mask]
  sign=-1 if idx==1 else 1; pref=t if idx==1 else np.ones(len(t))
  out=least_squares(lambda p:(pref*np.exp(p[0]+sign*p[1]/t)-y)/se,[0,2])
  cov=np.linalg.inv(out.jac.T@out.jac)
  print(m['experiment'],nu,'logA, Delta',out.x,'SE',np.sqrt(cov.diagonal()),'chi2/dof',sum(out.fun**2)/(len(t)-2),'N',len(t))
  if idx==1:
   op=least_squares(lambda p:(np.exp(p[0]+p[2]*np.log(t)-p[1]/t)-y)/se,[out.x[0],out.x[1],1])
   cv=np.linalg.inv(op.jac.T@op.jac)
   print('Free prefactor power:',op.x,'SE',np.sqrt(cv.diagonal()),'chi2/dof',sum(op.fun**2)/(len(t)-3))
PY","max_output_tokens":3000}));
